TUS = [
    {"tu": "a.cpp", "defs": [("helper", "strong"), ("inline_util", "inline"),
                             ("local_only", "static")]},
    {"tu": "b.cpp", "defs": [("inline_util", "inline"), ("local_only", "static"),
                             ("tmpl_inst", "weak")]},
    {"tu": "c.cpp", "defs": [("tmpl_inst", "weak"), ("inline_util", "inline")]},
]
BAD_TUS = [
    {"tu": "x.cpp", "defs": [("format", "strong"), ("detail_helper", "static")]},
    {"tu": "y.cpp", "defs": [("format", "inline"), ("detail_helper", "strong")]},
]

LINKAGE_NOTE = {
    "strong": "外部链接（唯一）",
    "weak": "弱符号/COMDAT，可由链接器折叠",
    "inline": "inline 函数/模板实例化，多个定义合法",
    "static": "内部链接，各 TU 各自私有",
}


def collect(tus):
    sym = {}
    for tu in tus:
        for name, kind in tu["defs"]:
            sym.setdefault(name, []).append((tu["tu"], kind))
    return sym


def check(tus):
    problems = []
    lines = []
    for name in sorted(collect(tus)):
        defs = collect(tus)[name]
        kinds = [k for _, k in defs]
        detail = ", ".join("%s(%s)" % (t, k) for t, k in defs)
        if kinds.count("strong") >= 2:
            v = "ODR 违规：%d 个强符号定义 -> multiple definition，链接期报错" % kinds.count("strong")
            problems.append((name, v))
        elif "strong" in kinds and ("inline" in kinds or "weak" in kinds):
            v = "ODR 违规：强符号与 inline/weak 混用，语义未定义（标准要求全程序一致）"
            problems.append((name, v))
        elif "inline" in kinds:
            v = "合法：%d 处 inline 定义由链接器合并为一份" % kinds.count("inline")
        elif "strong" in kinds:
            v = "合法：全程序仅一处强符号定义（外部链接）"
        elif "weak" in kinds:
            v = "合法：%d 处弱符号（模板实例化），链接器任选一份" % kinds.count("weak")
        else:
            v = "合法：内部链接，%d 个 TU 各持一份互不冲突" % kinds.count("static")
        lines.append("  %-14s 定义=%s" % (name, detail))
        lines.append("  %-14s %s" % ("", v))
    return lines, problems


print("[链路说明] strong=外部唯一 / weak=可折叠 / inline=多定义合法 / static=内部链接")
for label, tus, want_clean in (("用例1 正常", TUS, True), ("用例2 违规", BAD_TUS, False)):
    lines, problems = check(tus)
    print("[%s] TU=%s" % (label, [t["tu"] for t in tus]))
    for l in lines:
        print(l)
    print("  -> ODR 违规数=%d 链接结果=%s" % (len(problems), "失败" if problems else "成功"))
    assert (not problems) == want_clean, "判定与预期不符: " + label
print("[判定] ODR 检查器：正常用例 0 违规、违规用例 2 违规 -> 可区分正反两组 = True")
